// webpack.config.js

require('dotenv').config();

const path                  = require('path');
const CompressionPlugin     = require("compression-webpack-plugin");
const zlib                  = require("zlib");
const MiniCssExtractPlugin  = require("mini-css-extract-plugin");
const TerserPlugin          = require("terser-webpack-plugin");

let outputDivider = "../../distr/plugin/";
let entryDivider = "../../src/plugin/divider/index.js";

module.exports =
{
    mode: 'production',
    resolve:
    {
        extensions: ['.js', '.scss']
    },
    devtool: false,
    entry :
    {
        core : path.resolve(__dirname, entryDivider)
    },
    output :
    {
        pathinfo : false,
        path : path.resolve(__dirname, outputDivider),
        filename : 'divider/js/divider.min.js',
    },
    optimization :
    {
        minimize: true,
        minimizer: [
            new TerserPlugin({
                test: /\.js(\?.*)?$/i,
                minify: TerserPlugin.uglifyJsMinify,
                terserOptions: {},
            }),
        ],
    },
    module :
    {
        rules :
        [
            {
                test : /\.js$/,
                exclude : /node_modules/,
                use : ['babel-loader'],
            },
            {
                test : /\.(scss|css)$/,
                use:
                [
                    {
                        loader : MiniCssExtractPlugin.loader,
                        options :
                        {
                            publicPath : path.join(__dirname, outputDivider),
                        },
                    },
                    'css-loader',
                    {
                        loader: "postcss-loader",
                        options:
                        {
                            postcssOptions:
                            {
                                plugins:
                                [
                                ],
                            },
                        }
                    },
                    'sass-loader',
                ],
            },
        ]
    },
    plugins:
    [
        new MiniCssExtractPlugin(
            {
                filename: "divider/css/divider.min.css"
            }
        ),
        new CompressionPlugin({
            filename: "[path][base].br",
            algorithm: "brotliCompress",
            test: /\.(js|css|html|svg)$/,
            compressionOptions:
            {
                params:
                {
                    [zlib.constants.BROTLI_PARAM_QUALITY]: 11,
                },
            },
            threshold: 10240,
            minRatio: 0.8,
            deleteOriginalAssets: false,
        }),
    ]
}
